<?php
function admin_dashboard_rows($sql){return sc_query($sql)->get_result()->fetch_all(MYSQLI_ASSOC);}
function admin_dashboard_data($days=30){
 $days=in_array((int)$days,[0,7,30,90,365],true)?(int)$days:30;$group=(int)userVariable('user_group');$site=(int)userVariable('treatment_site');$all=in_array($group,[1,2],true);$clinical=$all?'':' AND site_id='.$site;$patients=$all?'':' AND EXISTS (SELECT 1 FROM consultations c WHERE c.patient_id=patients.id AND c.site_id='.$site.' AND c.is_deleted=0)';$from=$days===0?" '1970-01-01' ":" DATE_SUB(CURDATE(), INTERVAL ".($days-1)." DAY)";$bucket=$days===0?'%Y-%m':'%Y-%m-%d';$data=['days'=>$days,'cards'=>[],'alerts'=>[],'patients'=>[],'consultations'=>[],'stock'=>[],'orders'=>[],'chart'=>['revenue'=>['labels'=>[],'values'=>[]],'activity'=>['labels'=>[],'patients'=>[],'consultations'=>[]]]];
 if(admin_can('patient')){$r=admin_dashboard_rows("SELECT COUNT(*) total,COALESCE(SUM(created_at >= $from),0) period,COALESCE(SUM(created_at >= CURDATE()),0) today FROM patients WHERE is_active=1 AND is_deleted=0 $patients")[0];$data['cards'][]=['New patients',$r['period'],$r['today'].' today / '.$r['total'].' active patients','patients/'];$data['patients']=admin_dashboard_rows("SELECT id,patientid,uhid,first_name,last_name,created_at FROM patients WHERE is_active=1 AND is_deleted=0 $patients ORDER BY created_at DESC,id DESC LIMIT 6");}
 if(admin_can('consultation')){$r=admin_dashboard_rows("SELECT COUNT(*) total,COALESCE(SUM(created_at >= $from),0) period,COALESCE(SUM(is_report_finalized=0),0) pending FROM consultations WHERE is_active=1 AND is_deleted=0 $clinical")[0];$data['cards'][]=['Consultations',$r['period'],$r['total'].' active records','consultations/'];$data['alerts'][]=['Pending clinical reports',(int)$r['pending'],'consultations/','Reports awaiting finalization'];$scope=$all?'':' AND c.site_id='.$site;$data['consultations']=admin_dashboard_rows("SELECT c.id,c.consultationid,c.is_report_finalized,c.created_at,p.first_name,p.last_name FROM consultations c LEFT JOIN patients p ON p.id=c.patient_id WHERE c.is_active=1 AND c.is_deleted=0 $scope ORDER BY c.created_at DESC,c.id DESC LIMIT 6");$rows=admin_dashboard_rows("SELECT DATE_FORMAT(created_at,'$bucket') day,COUNT(*) n FROM consultations WHERE is_active=1 AND is_deleted=0 $clinical AND created_at >= $from GROUP BY day ORDER BY day");$data['chart']['activity']=['labels'=>array_column($rows,'day'),'patients'=>[],'consultations'=>array_map('intval',array_column($rows,'n'))];}
 if(admin_can('sale')){$r=admin_dashboard_rows("SELECT COUNT(*) total,COALESCE(SUM(grand_total),0) amount FROM sales WHERE is_active=1 AND is_deleted=0 AND is_sale_finalized=1 $clinical AND date >= $from")[0];$data['cards'][]=['Clinic sales value',sc_money((int)round($r['amount']*100)),$r['total'].' finalized sales; not cash receipts','sales/'];$r=admin_dashboard_rows("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN status<>'cancelled' THEN total ELSE 0 END),0) value FROM web_orders WHERE created_at >= $from")[0];$data['cards'][]=['Online orders',$r['total'],sc_money((int)round($r['value']*100)).' ordered value, excluding cancellations','online-orders/'];$pending=admin_dashboard_rows("SELECT COALESCE(SUM(status='placed'),0) dispatch,COALESCE(SUM(CASE WHEN status='delivered' AND payment_status='unpaid' THEN total ELSE 0 END),0) cod FROM web_orders")[0];$data['alerts'][]=['Awaiting dispatch',(int)$pending['dispatch'],'online-orders/','Placed orders ready for review'];$data['alerts'][]=['COD awaiting collection',sc_money((int)round($pending['cod']*100)),'online-orders/','Delivered orders with unpaid COD'];$data['orders']=admin_dashboard_rows('SELECT id,order_number,total,status,payment_status,created_at FROM web_orders ORDER BY id DESC LIMIT 6');$rows=admin_dashboard_rows("SELECT DATE_FORMAT(date,'$bucket') day,ROUND(SUM(grand_total),2) amount FROM sales WHERE is_active=1 AND is_deleted=0 AND is_sale_finalized=1 $clinical AND date >= $from GROUP BY day ORDER BY day");$data['chart']['revenue']=['labels'=>array_column($rows,'day'),'values'=>array_map('floatval',array_column($rows,'amount'))];}
 if(admin_can('inventory')){$scope=$all?'':' AND i.site_id='.$site;$data['stock']=admin_dashboard_rows("SELECT i.id,i.quantity,p.product_name,s.site_name FROM inventory i JOIN products p ON p.id=i.product_id LEFT JOIN sites s ON s.id=i.site_id WHERE p.is_active=1 AND p.is_deleted=0 AND i.quantity<=5 $scope ORDER BY i.quantity,i.id LIMIT 8");$r=admin_dashboard_rows("SELECT COUNT(*) n,COALESCE(SUM(i.quantity=0),0) empty FROM inventory i JOIN products p ON p.id=i.product_id WHERE p.is_active=1 AND p.is_deleted=0 AND i.quantity<=5 $scope")[0];$data['alerts'][]=['Low-stock locations',(int)$r['n'],'inventory/',$r['empty'].' out of stock; threshold 5 units'];}
 return $data;
}
